const profileKey = "insight.profile"

// profileOverride is the manual profile; zero values fall back to the FIT
// files.
type profileOverride struct {
	BirthYear int    `json:"birth_year,omitempty"`
	Sex       string `json:"sex,omitempty"` // "male" or "female"
}

// fitProfile is the profile found in the newest FIT files.
type fitProfile struct {
	Age    int // at the time of the activity
	Gender string
	At     time.Time
	OK     bool
}

// profileCache avoids decoding FIT files on every page view.
type profileCache struct {
	mu      sync.Mutex
	fit     fitProfile
	fetched time.Time
}

const profileCacheTTL = time.Hour

func (s *server) fitProfile(ctx context.Context) fitProfile {
	if s.Importer == nil {
		return fitProfile{}
	}
	c := &s.profiles
	c.mu.Lock()
	defer c.mu.Unlock()
	if !c.fetched.IsZero() && s.now().Sub(c.fetched) < profileCacheTTL {
		return c.fit
	}
	p, at, ok, err := s.Importer.LatestProfile(ctx)
	if err != nil {
		s.Logger.Warn("fit profile", "err", err)
		return c.fit
	}
	c.fit, c.fetched = fitProfile{Age: p.Age, Gender: p.Gender, At: at, OK: ok}, s.now()
	return c.fit
}

func (s *server) profileOverride(ctx context.Context) profileOverride {
	var o profileOverride
	if raw, ok, err := s.Store.Setting(ctx, profileKey); err == nil && ok {
		_ = json.Unmarshal([]byte(raw), &o)
	}
	return o
}

// profile combines the manual values with the FIT profile; the age of the
// FIT profile is advanced by the years since that activity.
func (s *server) profile(ctx context.Context) insight.Profile {
	o := s.profileOverride(ctx)
	today := localDate(s.now())
	var p insight.Profile
	sex := o.Sex
	if o.BirthYear > 0 {
		p.Age = today.Year() - o.BirthYear
	}
	if p.Age == 0 || sex == "" {
		if f := s.fitProfile(ctx); f.OK {
			if p.Age == 0 {
				p.Age = f.Age + int(today.Sub(f.At).Hours()/24/365.25)
			}
			if sex == "" {
				sex = f.Gender
			}
		}
	}
	if sex == "" {
		return insight.Profile{}
	}
	p.Female = sex == "female"
	return p
}

